from posts_20261025_a import P,POSTS

P(id='20261025-tourist-01', code='TOURIST', sec=['POLICE'],
 title='สตม. ตรวจสอบกรณีครอบครัวตามหาพิธีกรชาวดัตช์วัย 70 ปี พบข้อมูลเดินทางออกไทยไป สปป.ลาว ตั้งแต่ปลายปี 2568',
 agency='สื่อไทย > MGR Online', origin='indirect', prio='B', sev='low', ver='media_only', stage='ติดตามตัว', role='ปราบปรามเชิงรุก',
 prov=['ภูเก็ต','หนองคาย'], alert=False, imp=False, units=['สตม.','บก.สส.สตม.','บก.ตม.'],
 tags=['คนต่างชาติหาย','ตรวจสอบการเข้า-ออกประเทศ','ประสานครอบครัว'], mo=[], scale='ข้ามชาติ',
 pub='2026-10-24T13:26:00+07:00', src='https://mgronline.com/crime/detail/9690000102520',
 corr=[('เดลินิวส์','https://www.dailynews.co.th/news/6301956/'),('อมรินทร์ทีวี','https://www.amarintv.com/news/crime/561096')],
 stats=dict(arrested=None,suspects=None,victims=None,loss_thb=None,seized_value_thb=None),
 laws=[], pa=['ญาติของชาวต่างชาติที่ติดต่อไม่ได้ สามารถแจ้งสถานทูตและ ตม. เพื่อขอตรวจสอบประวัติการเข้า-ออกประเทศ','ระวังข่าวหรือโพสต์ตามหาคนหายที่แอบอ้างให้โอนเงินรางวัลก่อนให้ข้อมูล'],
 ao=['หน่วยงานดูแลนักท่องเที่ยวควรมีช่องทางประสานระหว่างสถานทูตกับตำรวจ','โรงแรมและที่พักควรแจ้งที่พักคนต่างด้าว (ตม.6) ครบถ้วนเพื่อประโยชน์ในการติดตามตัว'],
 op='ตรวจสอบประวัติการเดินทางเข้า-ออกประเทศของชาวต่างชาติที่ครอบครัวแจ้งว่าหายตัว', outcome='อื่น ๆ', note='ผบช.สตม. สั่ง ตม.ทั่วประเทศติดตามตัว; พบข้อมูลออกไทยทางสะพานมิตรภาพไป สปป.ลาว',
 content='MGR Online เดลินิวส์ และอมรินทร์ทีวีรายงานว่า เมื่อวันที่ 24 ตุลาคม 2569 กรณีเพจข่าวภูเก็ตและครอบครัวของพิธีกรโทรทัศน์ชาวดัตช์วัย 70 ปีรายหนึ่ง ประกาศตามหาตัวชายผู้นี้ว่าหายไปในประเทศไทย พร้อมตั้งรางวัลเบาะแส 2,500 ยูโร (ราว 1 แสนบาท) ครอบครัวระบุว่าไม่ได้ติดต่อกับเขาโดยตรงมาเกือบ 2 ปี และมีเบาะแสเกี่ยวกับเพื่อนสนิทหญิงชื่อต้นว่า “นาตาเลีย” ซึ่งเชื่อว่าพักอาศัยด้วยกัน ผู้บัญชาการสำนักงานตรวจคนเข้าเมือง (ผบช.สตม.) จึงสั่งให้ ผบก.ตม. ทุกหน่วยตรวจสอบและติดตามตัวโดยด่วน ตามที่ พล.ต.ต.เชิงรณ ริมผดี รอง ผบช.สตม. ในฐานะโฆษก สตม. แถลง ผลการตรวจสอบพบว่าชายผู้นี้และเพื่อนสนิทเดินทางเข้าไทยตั้งแต่เดือนธันวาคม 2564 ทางด่าน ตม.สนามบินสุวรรณภูมิ อยู่ในไทยด้วยวีซ่าที่ถูกต้อง และแจ้งที่พักอาศัยในจังหวัดแห่งหนึ่งในภาคกลางตอนใต้ จากนั้นพบข้อมูลว่าชายผู้นี้เดินทางออกจากไทยทางสะพานมิตรภาพไป สปป.ลาว ตั้งแต่ปลายปี 2568 ส่วนเพื่อนสนิทหญิงออกนอกประเทศในวันเดียวกันไปยังประเทศหนึ่งทางตะวันออกกลางทางเครื่องบินที่สนามบินสุวรรณภูมิ ปัจจุบันไม่ปรากฏข้อมูลในระบบ ตม. ว่าทั้งสองคนเดินทางกลับเข้าไทย ผบช.สตม. ยังสั่งให้ ผบก.สส.สตม. ติดตามข้อมูลเพิ่มเติมเพื่อประโยชน์ต่อการช่วยตามหาตัวให้ครอบครัวและหน่วยงานรักษาความปลอดภัยนักท่องเที่ยวต่างชาติ ตามที่ สตม. ยืนยันว่าให้ความสำคัญกับการคัดกรองคนต่างชาติทั้งกลุ่มเสี่ยงถูกหลอกและกลุ่มเสี่ยงต่อความมั่นคง ตามนโยบายของ ผบ.ตร. ข่าวนี้ยังไม่ใช่คดีอาญา และไม่มีผู้ต้องหาหรือข้อกล่าวหาใด ๆ ข้อมูลที่ได้เป็นผลการตรวจสอบทางทะเบียนเข้า-ออกเมืองเท่านั้น และสถานะปัจจุบันของบุคคลดังกล่าวยังไม่อาจยืนยันได้จากข่าว')

P(id='20261025-drug-05', code='DRUG', sec=['CYBER'],
 title='ตำรวจบางละมุงจับ “เจ๊เบียร์ คนละยำ” ตามหมายจับ ข้อหาชักชวนผู้อื่นเสพยาและเสพไอซ์โชว์ในไลฟ์สด ผู้ต้องหายอมรับใช้ไอซ์ ตำรวจเตรียมแจ้งเพิ่มข้อหาพ.ร.บ.คอมพิวเตอร์',
 agency='สื่อไทย > ไทยรัฐ', origin='indirect', prio='B', sev='medium', ver='single_source', stage='จับกุม', role='สืบสวนจับกุม',
 prov=['ชลบุรี','ประจวบคีรีขันธ์'], alert=False, imp=False, units=['สภ.บางละมุง','ศาลจังหวัดพัทยา'],
 tags=['เสพยาในไลฟ์สด','หมายจับศาลพัทยา','อินฟลูเอนเซอร์'], mo=[], scale='ท้องถิ่น',
 pub='2026-10-24T10:52:00+07:00', src='https://www.thairath.co.th/news/crime/2968052', corr=[],
 stats=dict(arrested=1,suspects=1,victims=None,loss_thb=None,seized_value_thb=None),
 laws=['ชักนำ ยุยง ส่งเสริมให้ผู้อื่นเสพยาเสพติดประเภท 1','เสพเมทแอมเฟตามีน','พ.ร.บ.คอมพิวเตอร์ (ที่ตำรวจจะแจ้งเพิ่ม)'],
 pa=['ไม่สนับสนุนหรือแชร์คลิปไลฟ์สดที่เสพสารเสพติด และรายงานเนื้อหาต่อแพลตฟอร์ม','ผู้ต้องการเลิกยาเสพติดติดต่อสายด่วน 1165'],
 ao=['แพลตฟอร์มไลฟ์สดควรมีระบบตรวจจับเนื้อหาเสพสารเสพติดและระงับกระแสสดทันที','หน่วยสาธารณสุขควรมีช่องทางประสานผู้มีอิทธิพลโซเชียลเพื่อชักชวนเข้ารับการบำบัด'],
 op='ใช้หมายจับศาลจังหวัดพัทยาจับที่บ้านพักในประจวบคีรีขันธ์ แล้วนำตัวมาสอบสวนที่ สภ.บางละมุง', outcome='จับกุม', note='เหตุจากคลิปไลฟ์สดใน TikTok ที่โรงแรมรายวัน อ.บางละมุง มีผู้ชมกว่า 4 พันคน',
 content='ไทยรัฐรายงานว่า ชุดสืบสวน สภ.บางละมุง ใช้หมายจับศาลจังหวัดพัทยาเลขที่ 599/2569 จับชายวัย 39 ปี ผู้เป็นที่รู้จักในโซเชียลฉายา “เจ๊เบียร์ คนละยำ” ที่บ้านพักใน อ.เมือง จ.ประจวบคีรีขันธ์ ข้อหาจูงใจ ชักนำ ยุยงส่งเสริม ใช้อุบายหลอกลวง ขู่เข็ญ หรือใช้กำลังบังคับให้ผู้อื่นเสพยาเสพติดประเภท 1 และข้อหาเสพยาเสพติดประเภท 1 (เมทแอมเฟตามีน) โดยฝ่าฝืนกฎหมาย หลังเกิดเหตุไลฟ์สดบน TikTok ที่ปรากฏพฤติกรรมคล้ายเสพยาเสพติดภายในโรงแรมรายวันแห่งหนึ่ง อ.บางละมุง จ.ชลบุรี ผู้ชมกว่า 4 พันคน ตำรวจนำตัวมาถึง สภ.บางละมุง เมื่อเวลา 23.00 น. วันที่ 23 ตุลาคม 2569 ผู้ต้องหาให้สัมภาษณ์ว่ายอมรับว่าเสพไอซ์มาโดยตลอด และเสพโชว์ในไลฟ์สดเพราะแฟนคลับท้าทายให้โอนเงิน 1,000 บาทแลกกับการเสพโชว์ ซึ่งมีเงินโอนเข้าบัญชีจริงทันที ผู้ต้องหาระบุว่าทำเพราะไม่อยากคืนคำและบางครั้งอยากประชดชีวิต ยอมรับว่าสิ่งที่ทำไม่ดี แต่ไม่ได้ขาดสติ และจะไม่ขอโทษแฟนคลับเพราะเป็นความผิดของตนเอง ตำรวจชุดสืบสวนจะสอบสวนเพิ่มเติมและแจ้งข้อกล่าวหาเพิ่ม 1 ข้อหา ตาม พ.ร.บ.คอมพิวเตอร์ ฐานนำเข้าข้อมูลที่อาจก่อความตื่นตระหนกหรือกระทบความมั่นคง รวมเป็น 3 ข้อหา ก่อนส่งตัวให้พนักงานสอบสวนดำเนินคดี ข่าวนี้สะท้อนปัญหาที่การเผยแพร่พฤติกรรมเสพสารเสพติดผ่านไลฟ์สดเข้าถึงผู้ชมจำนวนมากและอาจกระตุ้นให้ผู้อื่นเลียนแบบ ส่วนการเรียกรับเงินโอนระหว่างไลฟ์สดเป็นพฤติการณ์ที่ตำรวจอาจพิจารณาประกอบข้อหาชักนำ ทั้งนี้ ผู้ต้องหายังถือเป็นผู้บริสุทธิ์จนกว่าศาลจะมีคำพิพากษา')

P(id='20261025-property-01', code='PROPERTY', sec=['ECON'],
 title='ตำรวจบางศรีเมืองจับชายวัย 28 ปี ผู้ต้องหาลักทรัพย์ในเคหสถาน นนทบุรี มูลค่ากว่า 2 ล้านบาท ให้การว่าเป็นหนี้จากเทรดทองตามโฆษณาโซเชียล',
 agency='สื่อไทย > เดลินิวส์', origin='indirect', prio='B', sev='medium', ver='media_only', stage='จับกุม', role='สืบสวนจับกุม',
 prov=['นนทบุรี'], alert=True, imp=False, units=['สภ.บางศรีเมือง'],
 tags=['ลักทรัพย์ในหมู่บ้าน','หนี้จากเทรดทอง','หลอกลงทุนโซเชียล'], mo=['หลอกลงทุนหุ้น/ฟอเร็กซ์'], scale='ท้องถิ่น',
 pub='2026-10-24T23:45:00+07:00', src='https://www.dailynews.co.th/news/6302253/',
 corr=[('MGR Online','https://mgronline.com/crime/detail/9690000102559')],
 stats=dict(arrested=1,suspects=1,victims=1,loss_thb=2000000,seized_value_thb=None),
 laws=['ลักทรัพย์ในเคหสถาน โดยทำอันตรายสิ่งกีดกั้น ใช้ยานพาหนะ'],
 pa=['คลิปชวนลงทุนเทรดทองหรือสินทรัพย์ในโซเชียลที่อ้างกำไรสูงเสี่ยงสูญเงิน ควรตรวจสอบรายชื่อผู้ให้บริการกับ ก.ล.ต. ก่อน','เจ้าของบ้านควรติดกล้องวงจรปิดที่ดูย้อนหลังได้และเก็บทรัพย์มีค่าในที่ปลอดภัย'],
 ao=['นิติบุคคลหมู่บ้านควรตรวจสอบระบบคีย์การ์ด ไม้กั้น และกล้องวงจรปิดย้อนหลังให้ใช้งานได้จริง','สถาบันการเงินควรเตือนผู้กู้นอกระบบและแอปกู้เงินเรื่องความเสี่ยงเกินความสามารถชำระ'],
 op='แกะรอยจากกล้องวงจรปิดและรถกระบะต้องสงสัย จับห้องพัก ต.คลองข่อย อ.ปากเกร็ด', outcome='จับกุม', note='ตรวจยึดสร้อยคอทอง แหวนทอง พระเครื่องเลี่ยมทอง และใบรับจำนำ',
 content='เดลินิวส์และ MGR Online รายงานว่า ชุดสืบสวน สภ.บางศรีเมือง จังหวัดนนทบุรี จับกุมชายอายุ 28 ปี (ไม่เปิดเผยนามสกุล) ผู้ต้องหาคดีลักทรัพย์ในเคหสถาน ได้ที่ห้องพัก ต.คลองข่อย อ.ปากเกร็ด เมื่อวันที่ 24 ตุลาคม 2569 พร้อมของกลางเป็นสร้อยคอทองคำ แหวนทอง พระเครื่องเลี่ยมทอง ตลับใส่ทอง และใบรับจำนำทอง ความเสียหายกว่า 2 ล้านบาท เรื่องสืบเนื่องจากวันที่ 16 ตุลาคม ผู้เสียหายอายุ 62 ปีแจ้งความว่าคนร้ายงัดบ้านพักในหมู่บ้านแห่งหนึ่ง ต.ไทรม้า อ.เมืองนนทบุรี ได้ทรัพย์สินไปหลายรายการ ตำรวจตรวจกล้องวงจรปิดพบรถกระบะโตโยต้า รีโว่ สีดำที่ผู้ต้องหาใช้ จึงเฝ้าสังเกตการณ์และเข้าค้นห้องพัก ผู้ต้องหาให้การรับสารภาพว่าจบปริญญาตรีสาขาวิศวกรรมไฟฟ้า ทำงานตำแหน่งรองหัวหน้าผู้จัดการ เงินเดือน 30,000-40,000 บาท แต่เห็นคลิปชวนลงทุนเทรดทองคำในแอป TikTok จึงหลงเชื่อลงทุน ช่วงแรกได้กำไรหลักร้อย ต่อมาเสียเงินครั้งละ 5,000-6,000 บาท ภายใน 1 สัปดาห์สูญไปกว่า 200,000 บาท ทั้งเงินเก็บ เงินกู้นอกระบบ แอปยืมเงิน และเงินยืมเพื่อนร่วมงาน จนถูกทวงหนี้หนัก จึงขี่ไรเดอร์ตระเวนหาบ้านที่ไม่ติดกล้องวงจรปิด ปีนเข้าทางหน้าต่าง แล้วนำทองไปจำนำได้ 120,000 บาทเพื่อใช้หนี้ ผู้ต้องหาฝากเตือนว่าอย่าโลภตามโฆษณาในโซเชียล ผู้เสียหายสะท้อนว่าจ่ายค่าคีย์การ์ดทุกเดือนแต่หมู่บ้านปล่อยให้คนนอกเข้าออกได้โดยไม่แลกบัตร ไม้กั้นไม่ใช้งาน และกล้องของนิติบุคคลดูย้อนหลังไม่ได้ ตำรวจแจ้งข้อหาลักทรัพย์ในเคหสถานโดยทำอันตรายสิ่งกีดกั้น ใช้ยานพาหนะเพื่อสะดวกแก่การกระทำผิดหรือพาทรัพย์นั้นไป ส่งดำเนินคดีต่อไป ผู้ต้องหายังถือเป็นผู้บริสุทธิ์จนกว่าศาลจะมีคำพิพากษา')

P(id='20261025-violent-04', code='VIOLENT', sec=['PROPERTY'],
 title='เจ้าของโรงงานวัย 72 ปี ยิงผู้บุกรุกเสียชีวิตที่โกดัง อ.กระทุ่มแบน สมุทรสาคร อ้างป้องกันตัว ตำรวจตรวจสอบข้อเท็จจริง ตามคำให้การ',
 agency='สื่อภาษาอังกฤษ/สากล > Pattaya Mail', origin='indirect', prio='C', sev='high', ver='single_source', stage='เกิดเหตุ', role='สอบสวน',
 prov=['สมุทรสาคร'], alert=False, imp=False, units=['สภ.กระทุ่มแบน'],
 tags=['ป้องกันตัว','ขโมยโกดัง','อาวุธปืน'], mo=[], scale='ท้องถิ่น',
 pub='2026-10-23T20:49:00+07:00', src='https://www.pattayamail.com/news/factory-owner-shoots-suspected-thief-dead-in-samut-sakhon-569500', corr=[],
 stats=dict(arrested=None,suspects=1,victims=1,loss_thb=None,seized_value_thb=None),
 laws=['คดีอาญาตามกระบวนการสอบสวน (เหตุป้องกันตัว ต้องพิจารณาตามกฎหมาย)'],
 pa=['พบผู้บุกรุกอย่าเผชิญหน้าลำพัง ให้ติดต่อ 191 และรอเจ้าหน้าที่','ติดตั้งกล้องวงจรปิดและแจ้งเหตุซ้ำเพื่อให้ตำรวจเพิ่มการลาดตระเวน'],
 ao=['เจ้าของโรงงานเก่า/โกดังที่ไม่ใช้งานควรเพิ่มระบบรักษาความปลอดภัยแทนการปกป้องด้วยอาวุธ','ตำรวจควรเพิ่มรอบตรวจพื้นที่โกดังที่ถูกขโมยซ้ำ'],
 op='ตรวจสถานที่เกิดเหตุและชันสูตรพลิกศพ เวลาราว 10.00 น. ต.สวนหลวง', outcome='อื่น ๆ', note='ผู้ยิงรออยู่ที่เกิดเหตุและให้ความร่วมมือ; ตำรวจยังตามหาผู้บุกรุกอีก 3 คน',
 content='Pattaya Mail รายงานว่า เมื่อวันที่ 23 ตุลาคม 2569 เจ้าของโรงงานวัย 72 ปีรายหนึ่งยิงชายที่ต้องสงสัยว่าเป็นขโมยเสียชีวิตขณะบุกรุกโกดังอุตสาหกรรมใน ต.สวนหลวง อ.กระทุ่มแบน จ.สมุทรสาคร ตำรวจและเจ้าหน้าที่พิสูจน์หลักฐานตรวจที่เกิดเหตุราว 10.00 น. หลังได้รับแจ้ง พบศพชายอายุราว 40 ปีมีบาดแผลกระสุนใต้หน้าอกซ้าย กระสุนฝังอยู่ในร่างกายบริเวณใกล้หัวใจ ยังไม่ทราบชื่อผู้เสียชีวิตขณะอยู่ที่เกิดเหตุ ผู้ยิงซึ่งเรียกด้วยชื่อสั้นว่า “พอ” ยังอยู่ที่เกิดเหตุรอตำรวจ ให้การว่าภรรยาโทรแจ้งว่ามีผู้บุกรุกโกดังอีกครั้ง โกดังนี้ถูกขโมยซ้ำหลายครั้งและเคยมีผู้ต้องสงสัยหลายรายถูกจับเมื่อ 4-5 เดือนก่อนแต่เหตุกลับเกิดซ้ำ เขาสร้างโรงงานเมื่อ 4-5 ปีก่อนเพื่อผลิตสินค้าโลหะ แต่ไม่ได้เริ่มดำเนินการเพราะสภาพเศรษฐกิจ เครื่องจักรเก่าจึงเก็บไว้ที่นั่น และคนร้ายมักขโมยแผงวงจรเพื่อเอาชิปหรือทองแดง ตามคำให้การเบื้องต้น เขากลับบ้านไปหยิบปืนลูกโม่ขนาด .38 ขับรถมาโกดังกับภรรยาและลูกสาวโดยให้รออยู่ข้างนอก ได้ยินเสียงเหมือนการตัดอุปกรณ์ด้านหลัง และมีชายคนหนึ่งเดินเข้ามาพร้อมท่อโลหะ จึงยิง 1 นัดเพื่อป้องกันตัว ชายอีก 3 คนหนีออกทางด้านหลัง ตำรวจนำตัวผู้ยิงและครอบครัวไปสอบปากคำที่ สภ.กระทุ่มแบน และกำลังตรวจสอบพฤติการณ์พร้อมติดตามผู้บุกรุกที่เหลือ คดีอยู่ระหว่างกระบวนการทางกฎหมาย เพื่อนบ้านบอกว่าผู้ยิงเป็นคนสุภาพ และผู้เสียชีวิตไม่ใช่คนในพื้นที่ เนื้อหานี้ไม่ตัดสินว่าการยิงชอบด้วยกฎหมายหรือไม่ ซึ่งต้องรอผลสอบสวนและการพิสูจน์หลักฐาน')

P(id='20261025-violent-05', code='VIOLENT', sec=['POLICE','ROAD'],
 title='ตำรวจ สน.ภาษีเจริญ แจ้ง 4 ข้อหาชายวัยกลางคนที่ใช้ศอกกระทุ้งตำรวจจราจรขณะถูกเรียกตรวจ ใต้สถานี BTS บางหว้า',
 agency='สื่อไทย > ข่าวสดออนไลน์', origin='indirect', prio='C', sev='low', ver='single_source', stage='จับกุม', role='สอบสวน',
 prov=['กรุงเทพมหานคร'], alert=False, imp=False, units=['สน.ภาษีเจริญ'],
 tags=['ทำร้ายเจ้าพนักงาน','ป้ายทะเบียนดัดแปลง','ตรวจจราจร'], mo=[], scale='ท้องถิ่น',
 pub='2026-10-24T15:45:00+07:00', src='https://www.khaosod.co.th/crime/news_10449151', corr=[],
 stats=dict(arrested=1,suspects=1,victims=1,loss_thb=None,seized_value_thb=None),
 laws=['ทำร้ายร่างกายเจ้าพนักงานขณะปฏิบัติหน้าที่','ต่อสู้ขัดขวางการจับกุม','หมิ่นประมาท','ขับรถที่ขาดต่อภาษีประจำปี'],
 pa=['เมื่อถูกเจ้าพนักงานเรียกตรวจ ให้ให้ความร่วมมือและแสดงเอกสารตามสิทธิ หากเห็นว่าไม่เป็นธรรมให้ร้องเรียนภายหลังผ่านช่องทางทางการ','ไม่ดัดแปลงป้ายทะเบียนรถ เพราะมีความผิดตามกฎหมายจราจร'],
 ao=['หน่วยงานจราจรควรมีกล้องติดตัวเจ้าหน้าที่ขณะปฏิบัติงานเพื่อบันทึกเหตุ','องค์กรควรอบรมการลดความตึงเครียดให้เจ้าหน้าที่ตรวจจราจร'],
 op='กวดขันวินัยจราจรจุดเพชรราชพฤกษ์ ตรวจรถเก๋งป้ายทะเบียนดัดแปลง', outcome='จับกุม', note='ตำรวจนอกเวรและผู้เห็นเหตุ 3-4 คนช่วยควบคุมตัวผู้ก่อเหตุ',
 content='ข่าวสดออนไลน์รายงานว่า คลิปที่ผู้ใช้เฟซบุ๊กรายหนึ่งโพสต์แสดงเหตุตำรวจจราจรถูกชายขับรถเก๋งฮอนด้า แอคคอร์ด สีน้ำเงินใช้ศอกกระทุ้งเข้าที่กลางอกจนหงายหลังล้มลงกับพื้น ใต้สถานีรถไฟฟ้า BTS บางหว้า เขตภาษีเจริญ กรุงเทพฯ ผู้กำกับ สน.ภาษีเจริญ แถลงเมื่อวันที่ 24 ตุลาคม 2569 ว่า รองสารวัตรจราจรและเจ้าหน้าที่กำลังกวดขันวินัยจราจรที่จุดเพชรราชพฤกษ์ พบรถเก๋งคันดังกล่าวดัดแปลงแผ่นป้ายทะเบียน จึงเรียกให้หยุดตรวจ เมื่อผู้ขับขี่ชายลงจากรถแสดงท่าทีไม่พอใจ ไม่ยอมแสดงใบขับขี่ แล้วใช้ศอกกระทุ้งเข้าที่ลิ้นปี่ของเจ้าหน้าที่อย่างแรง ตามที่ตำรวจแถลง ผู้ต้องหาถูกควบคุมตัวไว้ได้โดยตำรวจนอกเวรที่ผ่านมาและผู้เห็นเหตุอีก 3-4 คน และถูกนำตัวไป สน.ภาษีเจริญ ถูกแจ้งข้อกล่าวหา 4 ข้อ ได้แก่ ทำร้ายร่างกายเจ้าพนักงานขณะปฏิบัติหน้าที่ ต่อสู้ขัดขวางการจับกุม หมิ่นประมาท และขับรถที่ขาดต่อภาษีประจำปี เจ้าหน้าที่ที่ถูกทำร้ายถูกส่งตัวไปโรงพยาบาล ผู้ต้องหายังถือเป็นผู้บริสุทธิ์จนกว่าศาลจะมีคำพิพากษา ข่าวนี้เป็นตัวอย่างความเสี่ยงของเจ้าหน้าที่ตรวจจราจรในการเข้าเผชิญหน้าผู้ขับขี่ และการดัดแปลงป้ายทะเบียนซึ่งเป็นความผิดที่ถูกกวดขันอยู่ ไม่มีข้อมูลเกี่ยวกับการตรวจพบสิ่งผิดกฎหมายอื่นในรถจากรายงานข่าว')

P(id='20261025-public-01', code='PUBLIC', sec=['ORGANIZED'],
 title='ชาวบ้านแหลมฟ้าผ่า สมุทรปราการ ผวา วัยรุ่น 2 กลุ่มไล่ทำร้ายกันกลางดึก ปาระเบิดไทยประดิษฐ์เกือบ 10 ลูก ผู้ใหญ่บ้านประสานตำรวจแล้ว',
 agency='สื่อไทย > ข่าวสดออนไลน์', origin='indirect', prio='C', sev='medium', ver='single_source', stage='เกิดเหตุ', role='ป้องกัน/เตือนภัย',
 prov=['สมุทรปราการ'], alert=True, imp=False, units=['ผู้ใหญ่บ้าน หมู่ 6 ต.แหลมฟ้าผ่า'],
 tags=['ระเบิดไทยประดิษฐ์','วัยรุ่นก่อเหตุ','ความหวาดกลัวในชุมชน'], mo=[], scale='ท้องถิ่น',
 pub='2026-10-24T17:25:00+07:00', src='https://www.khaosod.co.th/around-thailand/news_10449168', corr=[],
 stats=dict(arrested=None,suspects=None,victims=None,loss_thb=None,seized_value_thb=None),
 laws=[], pa=['พบเหตุวัยรุ่นก่อเหตุมีอาวุธหรือวัตถุระเบิด อย่าออกไปดู ให้อยู่ในที่ปลอดภัยและแจ้ง 191','ชุมชนควรส่งภาพกล้องวงจรปิดให้ตำรวจและอย่าโพสต์คลิปที่เปิดเผยตัวผู้ไม่เกี่ยวข้อง'],
 ao=['เทศบาลและผู้นำชุมชนควรเพิ่มแสงสว่างและกล้องวงจรปิดในซอยที่เกิดเหตุ','โรงเรียนและหน่วยงานเยาวชนควรเข้าร่วมประสานแก้ปัญหากลุ่มวัยรุ่นรวมกลุ่มก่อเหตุ'],
 op='ผู้ใหญ่บ้านประสานตำรวจและรายงานนายอำเภอ', outcome='เตือนภัย', note='ยังไม่มีรายงานการจับกุมจากข่าว; กล้องวงจรปิดของชาวบ้านบันทึกเหตุไว้',
 content='ข่าวสดออนไลน์รายงานว่า ชาวบ้านซอยแหลมฟ้าผ่า หมู่ 6 ต.แหลมฟ้าผ่า อ.พระสมุทรเจดีย์ จ.สมุทรปราการ แจ้งว่าเมื่อราว 01.00 น. ของคืนวันที่ 24 ตุลาคม 2569 บริเวณกลางซอยวัดแหลมฟ้าผ่าใกล้ทางเข้าซอยร่วมพัฒนา มีวัยรุ่น 2 กลุ่มรวมกว่า 20 คน ขับขี่และซ้อนท้ายรถจักรยานยนต์กว่า 10 คัน ไล่ทำร้ายกันโดยมีมีด ไม้ และระเบิดเป็นอาวุธ กล้องวงจรปิดของชาวบ้านบันทึกภาพวัยรุ่นขว้างระเบิดเกือบ 10 ลูก เสียงดังสนั่นไปทั้งซอย ทำให้ผู้ป่วย เด็ก และผู้สูงอายุหวาดกลัว หลังก่อเหตุทั้งสองกลุ่มแยกย้ายหลบหนี ผู้สื่อข่าวลงพื้นที่พบเศษระเบิดไทยประดิษฐ์และก้อนหินกระจายบนถนน เจ้าของร้านอาหารทะเลรายหนึ่งซึ่งใช้ชื่อสมมติตามที่ข่าวระบุ เล่าว่ากำลังนอนหลับอยู่ในบ้าน สะดุ้งตื่นเพราะเสียงโวยวายและระเบิดหลายครั้ง แต่ไม่กล้าออกไปดูเพราะกลัวถูกลูกหลง เช้าวันรุ่งขึ้นพบเศษดินและเศษระเบิดกระเด็นถูกรถที่จอดหน้าบ้านเสียหายเล็กน้อย ที่ผ่านมาในย่านนี้ไม่เคยเกิดเหตุเช่นนี้ ผู้ใหญ่บ้านหมู่ 6 อายุ 59 ปี กล่าวว่ากังวลต่อความปลอดภัยของชีวิตและทรัพย์สิน เพราะชุมชนมีผู้สูงอายุและผู้ป่วยจำนวนมาก จึงได้ประสานตำรวจและรายงานนายอำเภอแล้ว จากข่าวยังไม่มีข้อมูลว่าตำรวจจับกุมผู้ใดได้ หรือมีผู้ได้รับบาดเจ็บ จึงต้องติดตามความคืบหน้าจากตำรวจในพื้นที่ต่อไป เนื้อหานี้ไม่ระบุชื่อผู้เกี่ยวข้อง และไม่ระบุสูตรหรือวิธีทำวัตถุระเบิด')

